esp_err_t bsp_lcd_init(void) {
    gpio_config_t gc = {
        .pin_bit_mask = (1ULL << PIN_CS) | (1ULL << PIN_SCK) | (1ULL << PIN_SDA) | (1ULL << PIN_RESET),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    ESP_RETURN_ON_ERROR(gpio_config(&gc), TAG, "gpio");
    ESP_RETURN_ON_ERROR(backlight_init(), TAG, "backlight");

    gpio_set_level(PIN_CS, 1);
    gpio_set_level(PIN_SCK, 0);
    gpio_set_level(PIN_SDA, 0);
    gpio_set_level(PIN_RESET, 1);
    vTaskDelay(pdMS_TO_TICKS(10));
    gpio_set_level(PIN_RESET, 0);
    vTaskDelay(pdMS_TO_TICKS(20));
    gpio_set_level(PIN_RESET, 1);
    vTaskDelay(pdMS_TO_TICKS(120));

    for (size_t i = 0; i < sizeof(s_init) / sizeof(s_init[0]); i++) {
        lcd_cmd(s_init[i].cmd);
        lcd_data(s_init[i].data, s_init[i].len);
        if (s_init[i].delay_ms) {
            vTaskDelay(pdMS_TO_TICKS(s_init[i].delay_ms));
        }
    }

    esp_lcd_rgb_panel_config_t rgb = {0};
    rgb.clk_src = LCD_CLK_SRC_DEFAULT;
    rgb.timings.pclk_hz = 18 * 1000 * 1000;
    rgb.timings.h_res = BSP_LCD_PHYS_W;
    rgb.timings.v_res = BSP_LCD_PHYS_H;
    rgb.timings.hsync_pulse_width = 6;
    rgb.timings.hsync_back_porch = 30;
    rgb.timings.hsync_front_porch = 30;
    rgb.timings.vsync_pulse_width = 40;
    rgb.timings.vsync_back_porch = 20;
    rgb.timings.vsync_front_porch = 20;
    rgb.data_width = 16;
    rgb.bits_per_pixel = 16;
    rgb.num_fbs = 2;
    rgb.bounce_buffer_size_px = 10 * BSP_LCD_PHYS_W;
    rgb.psram_trans_align = 64;
    rgb.hsync_gpio_num = PIN_HSYNC;
    rgb.vsync_gpio_num = PIN_VSYNC;
    rgb.de_gpio_num = PIN_DE;
    rgb.pclk_gpio_num = PIN_PCLK;
    rgb.disp_gpio_num = -1;
    for (int i = 0; i < 16; i++) {
        rgb.data_gpio_nums[i] = s_data_pins[i];
    }
    rgb.flags.fb_in_psram = 1;

    ESP_RETURN_ON_ERROR(esp_lcd_new_rgb_panel(&rgb, &s_panel), TAG, "rgb panel");
    ESP_RETURN_ON_ERROR(esp_lcd_panel_reset(s_panel), TAG, "reset");
    ESP_RETURN_ON_ERROR(esp_lcd_panel_init(s_panel), TAG, "init");

    s_logic = heap_caps_malloc(BSP_LCD_LOGIC_W * BSP_LCD_LOGIC_H * 2, MALLOC_CAP_SPIRAM);
    s_stage = heap_caps_malloc(BSP_LCD_PHYS_W * BSP_LCD_PHYS_H * 2, MALLOC_CAP_SPIRAM);
    if (!s_logic || !s_stage) {
        ESP_LOGE(TAG, "PSRAM framebuffer allocation failed");
        return ESP_ERR_NO_MEM;
    }
    bsp_lcd_fill(bsp_rgb565(4, 8, 16));
    ESP_RETURN_ON_ERROR(bsp_lcd_flush(), TAG, "flush");
    ESP_LOGI(TAG, "LCD ready: portrait timings %dx%d, logical %dx%d",
             BSP_LCD_PHYS_W, BSP_LCD_PHYS_H, BSP_LCD_LOGIC_W, BSP_LCD_LOGIC_H);
    return ESP_OK;
}

void bsp_lcd_fill(uint16_t rgb565) {
    if (!s_logic) {
        return;
    }
    size_t n = BSP_LCD_LOGIC_W * BSP_LCD_LOGIC_H;
    for (size_t i = 0; i < n; i++) {
        s_logic[i] = rgb565;
    }
}

static void draw_glyph(int lx, int ly, char c, uint16_t fg, uint16_t bg) {
    if (!s_logic || lx < 0 || ly < 0) {
        return;
    }
    unsigned idx = (c >= 32 && c < 127) ? (unsigned)(c - 32) : 0;
    /* 2x scale: cell 12x16 incl. spacing. */
    for (int row = 0; row < 7; row++) {
        uint8_t bits = s_font[idx][row];
        for (int col = 0; col < 5; col++) {
            int on = (bits >> (4 - col)) & 1;
            uint16_t color = on ? fg : bg;
            for (int dy = 0; dy < 2; dy++) {
                for (int dx = 0; dx < 2; dx++) {
                    int x = lx + col * 2 + dx;
                    int y = ly + row * 2 + dy;
                    if (x < BSP_LCD_LOGIC_W && y < BSP_LCD_LOGIC_H) {
                        s_logic[y * BSP_LCD_LOGIC_W + x] = color;
                    }
                }
            }
        }
    }
}

static void draw_text(int lx, int ly, const char *s, uint16_t fg, uint16_t bg) {
    int x = lx;
    for (const char *p = s; *p && x + 12 <= BSP_LCD_LOGIC_W; p++, x += 12) {
        draw_glyph(x, ly, *p, fg, bg);
    }
}

void bsp_lcd_show_text(const char lines[][65], int n_lines, const char *header) {
    uint16_t bg = bsp_rgb565(4, 8, 16);
    uint16_t fg = bsp_rgb565(235, 245, 255);
    uint16_t acc = bsp_rgb565(140, 220, 255);
    bsp_lcd_fill(bg);
    if (header) {
        char h[65];
        snprintf(h, sizeof h, "%s", header);
        draw_text(12, 8, h, acc, bg);
    }
    for (int i = 0; i < n_lines && i < 12; i++) {
        draw_text(12, 36 + i * 22, lines[i], fg, bg);
    }
}

esp_err_t bsp_lcd_flush(void) {
    if (!s_panel || !s_logic || !s_stage) {
        return ESP_ERR_INVALID_STATE;
    }
    /* 90-degree transpose: logical (lx,ly) -> portrait (ly, PHYS_H-1-lx). */
    for (int ly = 0; ly < BSP_LCD_LOGIC_H; ly++) {
        for (int lx = 0; lx < BSP_LCD_LOGIC_W; lx++) {
            int px = ly;
            int py = (BSP_LCD_PHYS_H - 1) - lx;
            s_stage[py * BSP_LCD_PHYS_W + px] = s_logic[ly * BSP_LCD_LOGIC_W + lx];
        }
    }
    return esp_lcd_panel_draw_bitmap(s_panel, 0, 0, BSP_LCD_PHYS_W, BSP_LCD_PHYS_H, s_stage);
}

