/* BOOT button: GPIO0, active-low, pull-up (vendor button_bsp.c facts).
 * Shares LCD CS (GPIO0) so the pin is sampled only after LCD init and with
 * a 50 ms debounce. Single press cycles the 3 screens within 300 ms.
 * RST is the system reset and is never used as app input. */

#define BSP_INPUT_DEBOUNCE_MS 50
#define BSP_INPUT_SCREEN_MS 300

esp_err_t bsp_input_init(void);

/* Call from a 5 ms poll task. Returns 1 once per debounced press. */
int bsp_input_poll_press(uint64_t now_ms);

/* Pure helper for host tests: debounce a raw level trace. */
int bsp_input_debounce_step(int raw_level_active_low_pressed,
                            uint64_t now_ms, uint64_t *stable_since,
                            int *stable_pressed);

#ifdef __cplusplus
}
#endif

#include "bsp_input.h"

#include "driver/gpio.h"
#include "esp_check.h"

#define PIN_BOOT 0

static uint64_t s_stable_since = 0;
static int s_stable_pressed = 0;
static int s_last_reported = 0;
static int s_inited = 0;

int bsp_input_debounce_step(int pressed, uint64_t now_ms, uint64_t *stable_since,
                            int *stable_pressed) {
    if (pressed != *stable_pressed) {
        if (*stable_since == 0) {
            *stable_since = now_ms;
        }
        if (now_ms - *stable_since >= BSP_INPUT_DEBOUNCE_MS) {
            *stable_pressed = pressed;
            *stable_since = 0;
            return 1;
        }
        return 0;
    }
    *stable_since = 0;
    return 0;
}

esp_err_t bsp_input_init(void) {
    gpio_config_t gc = {
        .pin_bit_mask = (1ULL << PIN_BOOT),
        .mode = GPIO_MODE_INPUT,
        .pull_up_en = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    ESP_RETURN_ON_ERROR(gpio_config(&gc), "bsp_input", "gpio0");
    s_stable_since = 0;
    s_stable_pressed = 0;
    s_last_reported = 0;
    s_inited = 1;
    return ESP_OK;
}

int bsp_input_poll_press(uint64_t now_ms) {
    if (!s_inited) {
        return 0;
    }
    int level = gpio_get_level(PIN_BOOT);
    int pressed = (level == 0);
    bsp_input_debounce_step(pressed, now_ms, &s_stable_since, &s_stable_pressed);
    int is_pressed = s_stable_pressed;
    int edge = is_pressed && !s_last_reported;
    s_last_reported = is_pressed;
    return edge;
}

/* Codex Desk Meter v2 firmware: USB CDM/1 receiver -> cache/stale -> LCD.
 *
 * Transport: USB-SERIAL-JTAG 115200 8N1 (baud is a host-side setting; the USB
 * function itself is rate-independent). No ACK/retry exists in cdm/1; the host
 * write receipt is not a device ACK. Console is routed to UART0 so the USB
 * port carries only canonical frames.
 */
#include <string.h>

#include "bsp_input.h"
#include "bsp_lcd.h"
#include "driver/usb_serial_jtag.h"
