#include "meter_state.h"
#include "meter_validate.h"
#include "nvs_flash.h"

static const char *TAG = "cdm_meter";

static meter_receiver_t s_rx;
static uint8_t *s_line;       /* accumulation buffer (64K+1) */
static size_t s_line_len;
static uint8_t *s_last_good;  /* last accepted raw line */
static size_t s_last_good_len;
static int s_screen;
static uint64_t s_screen_deadline_ms;
static autodim_state_t s_dim;
static int s_link_ok = 1;

static uint64_t now_s(void) {
    return (uint64_t)(esp_timer_get_time() / 1000000LL);
}

static uint64_t now_ms(void) {
    return (uint64_t)(esp_timer_get_time() / 1000LL);
}

static void persist_seq(void) {
    nvs_handle_t h;
    if (nvs_open("cdm", NVS_READWRITE, &h) != ESP_OK) {
        return;
    }
    uint32_t seq = s_rx.seq;
    nvs_set_u32(h, "rx_seq", seq);
    nvs_set_u8(h, "rx_has", s_rx.has_seq ? 1 : 0);
    nvs_commit(h);
    nvs_close(h);
}

static void restore_seq(void) {
    nvs_handle_t h;
    if (nvs_open("cdm", NVS_READONLY, &h) != ESP_OK) {
        return;
    }
    uint32_t seq = 0;
    uint8_t has = 0;
    if (nvs_get_u8(h, "rx_has", &has) == ESP_OK && has &&
        nvs_get_u32(h, "rx_seq", &seq) == ESP_OK) {
        s_rx.has_seq = 1;
        s_rx.seq = seq;
        ESP_LOGI(TAG, "restored receiver seq %lu", (unsigned long)seq);
    }
    nvs_close(h);
}

/* Extract up to 8 dashboard rows from the cached raw line. */
static int collect_dashboard(char rows[][65], int max_rows) {
    int n = 0;
    const uint8_t *beg = s_last_good;
    const uint8_t *end = s_last_good + s_last_good_len;
    const uint8_t *p = beg;
    while (n < max_rows && p < end) {
        const char *tok = "\"provider_id\"";
        size_t tl = strlen(tok);
        const uint8_t *found = NULL;
        for (const uint8_t *q = p; q + tl <= end; q++) {
            if (memcmp(q, tok, tl) == 0) {
                found = q;
                break;
            }
        }
        if (!found) {
            break;
        }
        char provider[32] = {0}, window[32] = {0};
        const uint8_t *scope_end = found + 2048 > end ? end : found + 2048;
        meter_json_find_string(found, scope_end, "provider_id", provider, sizeof provider);
        meter_json_find_string(found, scope_end, "window_id", window, sizeof window);
        double pct = 0;
        int is_null = 1;
        char pct_s[16] = {0};
        if (meter_json_find_number(found, scope_end, "percent_used", &pct, &is_null) && !is_null) {
            snprintf(pct_s, sizeof pct_s, "%g", pct);
        }
        char unit[16] = {0}, resets[32] = {0}, obs[32] = {0};
        meter_json_find_string(found, scope_end, "unit", unit, sizeof unit);
        meter_json_find_string(found, scope_end, "resets_at", resets, sizeof resets);
        meter_json_find_string(found, scope_end, "observed_at", obs, sizeof obs);
        gui_dashboard_line(provider[0] ? provider : NULL, window[0] ? window : NULL,
                           pct_s[0] ? pct_s : NULL, unit[0] ? unit : NULL,
                           resets[0] ? resets : NULL, obs[0] ? obs : NULL,
                           rows[n], 65);
        n++;
        p = found + tl;
    }
    return n;
}

static void render(void) {
    char header[65];
    snprintf(header, sizeof header, "CDM METER %s", gui_screen_name(s_screen));
    if (s_screen == 0) {
        char rows[8][65];
        memset(rows, 0, sizeof rows);
        int n = 0;
        if (s_rx.has_payload) {
            n = collect_dashboard(rows, 8);
        }
        if (n == 0) {
            snprintf(rows[0], sizeof rows[0], "BOOT: default (awaiting PC frame)");
            snprintf(rows[1], sizeof rows[1], "send cdm/1 via USB 115200 8N1");
            n = 2;
        }
        bsp_lcd_show_text(rows, n, header);
    } else if (s_screen == 1) {
        gui_screen_text_t t;
        if (s_rx.has_payload) {
            const uint8_t *beg = s_last_good;
            const uint8_t *end = s_last_good + s_last_good_len;
            char latest[32] = {0}, cap[32] = {0};
            int has = 0;
            /* Prefer codex-resets.com; fall back to any latest_reset_at. */
            const char *want = "\"codex-resets.com\"";
            const uint8_t *f = NULL;
            for (const uint8_t *q = beg; q + strlen(want) <= end; q++) {
                if (memcmp(q, want, strlen(want)) == 0) {
                    f = q;
                    break;
                }
            }
            const uint8_t *scope = f ? f : beg;
            const uint8_t *scope_end = scope + 1024 > end ? end : scope + 1024;
            if (meter_json_find_string(scope, scope_end, "latest_reset_at", latest, sizeof latest) && latest[0]) {
                has = 1;
            }
            meter_json_find_string(scope, scope_end, "captured_at", cap, sizeof cap);
            char age[32];
            snprintf(age, sizeof age, "%llus (rx-age)",
                     (unsigned long long)(now_s() - s_rx.received_monotonic_s));
            gui_global_text("codex-resets.com", latest[0] ? latest : NULL,
                            cap[0] ? cap : NULL, age, has, &t);
        } else {
            gui_global_text("codex-resets.com", NULL, NULL, NULL, 0, &t);
        }
        bsp_lcd_show_text(t.lines, t.count, header);
    } else {
        gui_screen_text_t t;
        char good[32] = {0};
        if (s_rx.has_payload) {
            snprintf(good, sizeof good, "%s", s_rx.sent_at);
        }
        gui_status_text(s_link_ok, s_rx.last_error[0] ? s_rx.last_error : NULL,
                        s_rx.stale, good[0] ? good : NULL,
                        s_link_ok ? "host-polls-5s" : "reopen<=1Hz", &t);
        bsp_lcd_show_text(t.lines, t.count, header);
    }
    bsp_lcd_flush();
    /* Backlight follows the separated feature module (never the core path). */
    bsp_backlight_set_brightness(255 - autodim_duty(&s_dim, now_s()));
}

static void rx_task(void *arg) {
    (void)arg;
    uint8_t chunk[1024];
    int empty_polls = 0;
    for (;;) {
        int n = usb_serial_jtag_read_bytes(chunk, sizeof chunk, pdMS_TO_TICKS(50));
        if (n <= 0) {
            if (++empty_polls > 100) {
                /* ~5 s without bytes: host reopen budget. Mark link lost but
                 * never reset the receiver sequence (contract). */
                s_link_ok = usb_serial_jtag_is_connected() ? 1 : 0;
                empty_polls = 0;
            }
            continue;
        }
        empty_polls = 0;
        s_link_ok = 1;
        s_dim.link_ok = 1;
        for (int i = 0; i < n; i++) {
            if (s_line_len >= METER_MAX_LINE + 1) {
                /* Oversized: reject, keep last-good, resync at next LF. */
                meter_receiver_update_stale(&s_rx, now_s());
                snprintf(s_rx.last_error, sizeof s_rx.last_error, "FRAME_OVERSIZED");
                if (chunk[i] == '\n') {
                    s_line_len = 0;
                }
                continue;
            }
            s_line[s_line_len++] = chunk[i];
            if (chunk[i] == '\n') {
                int rc = meter_receiver_accept(&s_rx, s_line, s_line_len, now_s(), NULL);
                if (rc == METER_FRAME_OK) {
                    memcpy(s_last_good, s_line, s_line_len);
                    s_last_good_len = s_line_len;
                    s_dim.last_activity_s = now_s();
                    persist_seq();
                    ESP_LOGI(TAG, "accepted seq %lu crc %s", (unsigned long)s_rx.seq,
                             s_rx.last_good_crc);
                } else {
                    ESP_LOGW(TAG, "rejected %s (kept seq %s%lu)", s_rx.last_error,
                             s_rx.has_seq ? "" : "none ",
                             (unsigned long)(s_rx.has_seq ? s_rx.seq : 0));
                }
                s_line_len = 0;
            }
        }
    }
}

static void ui_task(void *arg) {
    (void)arg;
    uint64_t last_flush_s = 0;
    render();
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(50));
        if (bsp_input_poll_press(now_ms())) {
            s_screen = (s_screen + 1) % 3;
            s_screen_deadline_ms = now_ms() + BSP_INPUT_SCREEN_MS;
            s_dim.last_activity_s = now_s();
            ESP_LOGI(TAG, "BOOT -> %s", gui_screen_name(s_screen));
            render();
            (void)s_screen_deadline_ms;
        }
        meter_receiver_update_stale(&s_rx, now_s());
        if (now_s() != last_flush_s) {
            last_flush_s = now_s();
            render(); /* 1 Hz refresh for ages/stale; LCD stays lit. */
        }
    }
}

void app_main(void) {
    ESP_ERROR_CHECK(nvs_flash_init());
    meter_receiver_init(&s_rx);
    restore_seq();
    /* Last-good payload lives in PSRAM so a 64K frame never touches DRAM. */
    s_line = heap_caps_malloc(METER_MAX_LINE + 2, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    s_last_good = heap_caps_malloc(METER_MAX_LINE + 2, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!s_line || !s_last_good) {
        ESP_LOGE(TAG, "PSRAM line buffers unavailable");
        return;
    }
    ESP_ERROR_CHECK(bsp_lcd_init());
    ESP_ERROR_CHECK(bsp_input_init());
    autodim_init(&s_dim, now_s());

    usb_serial_jtag_driver_config_t cfg = USB_SERIAL_JTAG_DRIVER_CONFIG_DEFAULT();
    cfg.rx_buffer_size = 8192;
    cfg.tx_buffer_size = 1024;
    esp_err_t rc = usb_serial_jtag_driver_install(&cfg);
    if (rc != ESP_OK) {
        ESP_LOGW(TAG, "usb_serial_jtag install rc=%d; receiver still polls", rc);
    }
    ESP_LOGI(TAG, "CDM meter boot: USB cdm/1 115200 8N1, LCD 820x320, BOOT cycles screens");

    xTaskCreatePinnedToCore(rx_task, "cdm_rx", 6144, NULL, 6, NULL, 0);
    xTaskCreatePinnedToCore(ui_task, "cdm_ui", 8192, NULL, 5, NULL, 1);
}

"""Offline fixture collector + normalizer (candidate product, PC side).

Reads only checkout fixtures. Preserves source/time/unit/error, never invents
windows or values, never touches credentials or the network.
"""
from __future__ import annotations

import argparse
import copy
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PROVIDER_ROOT = ROOT / "experiments" / "fixtures" / "providers"
FIXTURE_ROOT = ROOT / "experiments" / "fixtures"
STALE_SECONDS = 300
ABS_TOL = 0.01

DEFAULT_PROVIDER_FIXTURES = [
    "codex-percent-window.json",
    "claude-code-windows.json",
    "gemini-cli-unsupported.json",
    "antigravity-cli-unsupported.json",
    "orca-host-claude-code.json",
]
DEFAULT_GLOBAL_FIXTURES = [
    "codex-reset-forecast.json",
    "codex-resets-history.json",
]


class CollectError(ValueError):
    def __init__(self, code: str, message: str):
        self.code = code
        super().__init__(f"{code}: {message}")


def parse_ts(value, where: str) -> datetime:
    if not isinstance(value, str):
        raise CollectError("TIMESTAMP_INVALID", f"{where} must be RFC3339")
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise CollectError("TIMESTAMP_INVALID", f"{where} is not RFC3339: {value!r}")
    if dt.tzinfo is None:
        raise CollectError("TIMESTAMP_INVALID", f"{where} must include a timezone")
    return dt.astimezone(timezone.utc)


def load_json(path: Path):
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError:
        raise CollectError("FIXTURE_NOT_FOUND", str(path))
    except json.JSONDecodeError as exc:
        raise CollectError("FIXTURE_INVALID_JSON", f"{path}: {exc}")


def check_snapshot(snap: dict, reference: datetime) -> str | None:
    """Return an error_code string for invalid snapshots, else None.

    Valid snapshots (including error-carrying ones like unsupported/stale) pass
    schema-shape checks here; semantic violations return codes matching the
    provider-fixture-matrix vocabulary.
    """
    if not isinstance(snap, dict):
        return "SCHEMA_INVALID"
    for key in ("snapshot_id", "provider_id", "status", "observed_at", "windows",
                "stale", "last_good_at", "error_code"):
        if key not in snap:
            return "SCHEMA_INVALID"
    for w in snap.get("windows", []):
        for num_key in ("percent_used", "percent_remaining"):
            v = w.get(num_key)
            if v is not None and not isinstance(v, bool):
                if not isinstance(v, (int, float)) or not (0 <= v <= 100):
                    return "SCHEMA_INVALID"
        for num_key in ("used_units", "remaining_units", "limit_units"):
            v = w.get(num_key)
            if v is not None and (isinstance(v, bool) or not isinstance(v, (int, float)) or v < 0):
                return "SCHEMA_INVALID"
        pu, pr = w.get("percent_used"), w.get("percent_remaining")
        if pu is not None and pr is not None:
            if abs((pu + pr) - 100) > 0.01:
                return "SCHEMA_INVALID"
        uu, ru, lu = w.get("used_units"), w.get("remaining_units"), w.get("limit_units")
        if uu is not None and ru is not None and lu is not None:
            if abs((uu + ru) - lu) > ABS_TOL:
                return "ABSOLUTE_BALANCE_MISMATCH"
    ids = [w.get("window_id") for w in snap.get("windows", [])]
    if len(ids) != len(set(ids)):
        return "DUPLICATE_WINDOW"
    obs_raw = snap.get("observed_at")
    if obs_raw is not None:
        try:
            obs = parse_ts(obs_raw, "observed_at")
        except CollectError:
            return "SCHEMA_INVALID"
        if obs > reference:
            return "FUTURE_TIMESTAMP"
        age = (reference - obs).total_seconds()
        if snap.get("status") == "available" and age >= STALE_SECONDS:
            return "STALE_THRESHOLD_EXCEEDED"
    lg_raw = snap.get("last_good_at")
    if lg_raw is not None:
        try:
            lg = parse_ts(lg_raw, "last_good_at")
        except CollectError:
            return "SCHEMA_INVALID"
        if lg > reference:
            return "FUTURE_TIMESTAMP"
    return None


def collect_providers(names: list[str], reference: datetime):
    snapshots: list[dict] = []
    failures: list[dict] = []
    for name in names:
        path = (PROVIDER_ROOT / name).resolve()
        if not str(path).startswith(str(PROVIDER_ROOT.resolve())):
            failures.append({"adapter_id": name, "code": "FIXTURE_PATH_UNSAFE",
                             "message": "fixture must stay under providers/"})
            continue
        try:
            value = load_json(path)
            entries = value if isinstance(value, list) else [value]
            for entry in entries:
                code = check_snapshot(entry, reference)
                if code:
                    raise CollectError(code, f"{name} rejected: {code}")
                snapshots.append(copy.deepcopy(entry))
        except CollectError as exc:
            failures.append({"adapter_id": name, "code": exc.code, "message": str(exc)})
    return snapshots, failures


def normalize_global_reset(raw: dict) -> dict:
    """Wire model: logical provider->source, fetched_at->captured_at, v1."""
    if not isinstance(raw, dict):
        raise CollectError("GLOBAL_RESET_INVALID", "global reset input must be an object")
    for wire, logical in (("source", "provider"), ("captured_at", "fetched_at"),
                          ("latest_reset_at", "last_reset_at")):
        if wire in raw and logical in raw and raw[wire] != raw[logical]:
            raise CollectError("GLOBAL_RESET_ALIAS_CONFLICT", f"{wire} and {logical} disagree")
    captured = raw.get("captured_at", raw.get("fetched_at"))
    if captured is None:
        raise CollectError("CAPTURED_AT_REQUIRED", "captured_at is null: no valid wire")
    return {
        "schema_version": 1,
        "source": raw.get("source", raw.get("provider")),
        "captured_at": captured,
        "latest_reset_at": raw.get("latest_reset_at", raw.get("last_reset_at")),
        "forecast_24h_percent": raw.get("forecast_24h_percent"),
        "forecast_48h_percent": raw.get("forecast_48h_percent"),
        "forecast_is_schedule": False,
        "stale": bool(raw.get("stale", False)),
        "error_code": raw.get("error_code"),
    }


def collect_globals(names: list[str]):
    resets: list[dict] = []
    failures: list[dict] = []
    for name in names:
        try:
            raw = load_json(FIXTURE_ROOT / name)
            resets.append(normalize_global_reset(raw))
        except CollectError as exc:
            failures.append({"adapter_id": name, "code": exc.code, "message": str(exc)})
    return resets, failures


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--fixture", action="append", default=None,
                        help="provider fixture file name under experiments/fixtures/providers")
    parser.add_argument("--global-fixture", action="append", default=None)
    parser.add_argument("--reference-time", default="2026-09-10T00:04:59Z")
    parser.add_argument("--out-payload", type=Path, default=None)
    parser.add_argument("--out-report", type=Path, default=None)
    args = parser.parse_args(argv)
    try:
        reference = parse_ts(args.reference_time, "reference_time")
    except CollectError as exc:
        print(json.dumps({"status": "rejected", "error_code": exc.code}),
              file=sys.stderr)
        return 1
    providers = args.fixture or DEFAULT_PROVIDER_FIXTURES
    globals_ = args.global_fixture or DEFAULT_GLOBAL_FIXTURES
    snapshots, pfails = collect_providers(providers, reference)
    resets, gfails = collect_globals(globals_)
    payload = {"usage": snapshots, "global_resets": resets}
    report = {"status": "collected", "snapshots": len(snapshots),
              "global_resets": len(resets),
              "failures": pfails + gfails}
    line = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    if args.out_payload is not None:
        args.out_payload.write_text(line + "\n", encoding="utf-8")
    else:
        sys.stdout.write(line + "\n")
    if args.out_report is not None:
        args.out_report.write_text(json.dumps(report, ensure_ascii=False,
                                              sort_keys=True) + "\n", encoding="utf-8")
    print(json.dumps(report, ensure_ascii=False, sort_keys=True), file=sys.stderr)
    return 0 if not (pfails or gfails) else 2


if __name__ == "__main__":
    raise SystemExit(main())

"""cdm/1 USB-serial sender (candidate product, PC side).

Canonical JSON (sorted keys, no spaces, ensure_ascii=False, no NaN), CRC32
uppercase hex, single LF, <=65536 bytes, uint32 sequence with persistence.
Real serial access only via --send + --port (115200 8N1, no flow control,
reopen at most 1 Hz by the caller). Failed writes still consume the number.
State loss/corruption stops transmission; --init-alias re-provisions an
explicitly empty receiver only.
"""
from __future__ import annotations

import argparse
import json
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path

PROTOCOL = "cdm/1"
MAX_SEQUENCE = 2**32 - 1
HALF_RANGE = 2**31
MAX_FRAME_BYTES = 64 * 1024


class SendError(ValueError):
    def __init__(self, code: str, message: str):
        self.code = code
        super().__init__(f"{code}: {message}")


def canonical(value) -> bytes:
    try:
        return json.dumps(value, ensure_ascii=False, allow_nan=False,
                          sort_keys=True, separators=(",", ":")).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise SendError("CANONICAL_JSON_INVALID", str(exc))


def crc_hex(data: bytes) -> str:
    return f"{zlib.crc32(data) & 0xFFFFFFFF:08X}"


def check_rfc3339(value: str) -> None:
    if not isinstance(value, str):
        raise SendError("TIMESTAMP_INVALID", "sent_at must be RFC3339")
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise SendError("TIMESTAMP_INVALID", f"sent_at is not RFC3339: {value!r}")
    if dt.tzinfo is None:
        raise SendError("TIMESTAMP_INVALID", "sent_at must include a timezone")


def build_frame(payload: dict, sequence: int, sent_at: str) -> dict:
    if not isinstance(payload, dict):
        raise SendError("PAYLOAD_INVALID", "payload must be an object")
    if (not isinstance(sequence, int) or isinstance(sequence, bool)
            or not 0 <= sequence <= MAX_SEQUENCE):
        raise SendError("SEQUENCE_INVALID", "sequence must fit uint32")
    check_rfc3339(sent_at)
    usage = payload.get("usage")
    resets = payload.get("global_resets")
    if not isinstance(usage, list) or not isinstance(resets, list):
        raise SendError("PAYLOAD_INVALID", "payload requires usage and global_resets")
    unsigned = {"payload": payload, "protocol": PROTOCOL,
                "sent_at": sent_at, "sequence": sequence}
    value = crc_hex(canonical(unsigned))
    return {"integrity": {"algorithm": "crc32", "value": value},
            "payload": payload, "protocol": PROTOCOL,
            "sent_at": sent_at, "sequence": sequence}


def encode_frame(frame: dict) -> bytes:
    if frame.get("protocol") != PROTOCOL:
        raise SendError("UNSUPPORTED_VERSION", "protocol must be cdm/1")
    unsigned = {k: frame[k] for k in ("payload", "protocol", "sent_at", "sequence")}
    if crc_hex(canonical(unsigned)) != frame["integrity"]["value"]:
        raise SendError("CRC_MISMATCH", "integrity does not match envelope")
    line = canonical(frame) + b"\n"
    if len(line) > MAX_FRAME_BYTES:
        raise SendError("FRAME_OVERSIZED", "encoded frame exceeds 65536 bytes")
    return line


def sequence_is_newer(candidate: int, current: int) -> bool:
    distance = (candidate - current) & MAX_SEQUENCE
    return 0 < distance < HALF_RANGE


class SequenceStore:
    """Atomic per-alias next-sequence persistence."""

    def __init__(self, path: Path):
        self.path = Path(path)

    def load_next(self) -> int:
        try:
            raw = json.loads(self.path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            raise SendError("SENDER_STATE_MISSING",
                            f"no sequence state at {self.path}; use --init-alias")
        except (json.JSONDecodeError, UnicodeDecodeError):
            raise SendError("SENDER_STATE_CORRUPT", f"sequence state corrupt: {self.path}")
        if not isinstance(raw, dict) or "next" not in raw:
            raise SendError("SENDER_STATE_CORRUPT", f"sequence state corrupt: {self.path}")
        nxt = raw["next"]
        if not isinstance(nxt, int) or isinstance(nxt, bool) or not 0 <= nxt <= MAX_SEQUENCE:
            raise SendError("SENDER_STATE_CORRUPT", f"sequence state corrupt: {self.path}")
        return nxt

    def save_next(self, nxt: int) -> None:
        tmp = self.path.with_suffix(self.path.suffix + ".tmp")
        tmp.write_text(json.dumps({"next": nxt}, sort_keys=True) + "\n", encoding="utf-8")
        tmp.replace(self.path)

    def init_alias(self, receiver_empty_ack: bool) -> int:
        if self.path.exists():
            raise SendError("SENDER_STATE_EXISTS",
                            "alias already provisioned; refusing to re-init")
        if not receiver_empty_ack:
            raise SendError("RECEIVER_STATE_UNCONFIRMED",
                            "initial creation requires confirming the receiver is empty")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.save_next(1)
        return 1

    def reserve(self) -> int:
        nxt = self.load_next()
        self.save_next((nxt + 1) & MAX_SEQUENCE)
        return nxt


def send_serial(line: bytes, port: str) -> int:
    try:
        import serial
    except ImportError:
        raise SendError("SERIAL_BACKEND_UNAVAILABLE",
                        "install the owner-approved serial backend")
    ser = serial.Serial(port=port, baudrate=115200, bytesize=8,
                        parity="N", stopbits=1, xonxoff=False,
                        rtscts=False, dsrdtr=False, timeout=1)
    try:
        written = ser.write(line)
    finally:
        ser.close()
    if written != len(line):
        raise SendError("SERIAL_WRITE_INCOMPLETE", f"wrote {written} of {len(line)}")
    return written


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--payload", type=Path, required=True)
    parser.add_argument("--sent-at", required=True)
    parser.add_argument("--alias", default="usb-meter")
    parser.add_argument("--state-dir", type=Path, default=Path("out/pc_sender"))
    parser.add_argument("--output", type=Path, default=None)
    parser.add_argument("--raw-log", type=Path, default=None)
    parser.add_argument("--report-output", type=Path, default=None)
    parser.add_argument("--send", action="store_true")
    parser.add_argument("--port", default=None)
    parser.add_argument("--init-alias", action="store_true")
    parser.add_argument("--receiver-empty-ack", action="store_true")
    args = parser.parse_args(argv)
    try:
        if args.port and not args.send:
            raise SendError("PORT_REQUIRES_SEND", "--port is accepted only with --send")
        if args.send and not args.port:
            raise SendError("PORT_REQUIRED", "--send requires an explicit --port")
        try:
            payload = json.loads(args.payload.read_text(encoding="utf-8-sig"))
        except (FileNotFoundError, json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise SendError("PAYLOAD_INVALID", str(exc))
        store = SequenceStore(args.state_dir / f"{args.alias}.seq.json")
        if args.init_alias:
            seq = store.init_alias(args.receiver_empty_ack)
        else:
            seq = store.reserve()  # consumed even if the write below fails
        frame = build_frame(payload, seq, args.sent_at)
        line = encode_frame(frame)
        outcome = {"mode": "dry_run", "status": "rendered",
                   "sequence": seq, "bytes": len(line),
                   "frame_sha256": __import__("hashlib").sha256(line).hexdigest(),
                   "device_accessed": False}
        if args.output is not None:
            args.output.write_bytes(line)
            outcome["output_path"] = args.output.as_posix()
        if args.raw_log is not None:
            args.raw_log.parent.mkdir(parents=True, exist_ok=True)
            with open(args.raw_log, "ab") as handle:
                handle.write(line)
            outcome["raw_log"] = args.raw_log.as_posix()
        if args.send:
            written = send_serial(line, args.port)
            outcome.update(mode="serial", status="sent",
                           bytes_written=written, device_accessed=True)
        text = json.dumps(outcome, ensure_ascii=False, sort_keys=True)
        if args.report_output is not None:
            args.report_output.write_text(text + "\n", encoding="utf-8")
        print(text, file=sys.stderr)
        return 0
    except SendError as exc:
        text = json.dumps({"status": "rejected", "error_code": exc.code,
                           "message": str(exc)})
        if args.report_output is not None:
            args.report_output.write_text(text + "\n", encoding="utf-8")
        print(text, file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Legacy provider/global seam for scripts/evaluate-product.py.

Reads stdin UTF-8 JSON {source, events:[{now, body, error}]} and writes one
normalized snapshot per event to stdout. Fresh state per invocation; events
share one last-good within the invocation. Never contacts a provider.
"""
from __future__ import annotations

import copy
import json
import sys
from datetime import datetime, timezone


def parse_ts(value) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if dt.tzinfo is None:
        return None
    return dt.astimezone(timezone.utc)


def age_seconds(now: datetime, captured: datetime) -> float:
    return (now - captured).total_seconds()


def fixture_snapshot(body: dict, now: datetime, error_code, last_good) -> dict:
    captured_raw = body.get("captured_at") if isinstance(body, dict) else None
    captured = parse_ts(captured_raw)
    windows = body.get("windows") if isinstance(body, dict) else None
    if last_good is not None and (not isinstance(body, dict) or captured is None
                                  or not isinstance(windows, list)):
        out = copy.deepcopy(last_good)
        out["stale"] = False
        out["error_code"] = error_code or "CAPTURED_AT_INVALID"
        return out
    assert isinstance(body, dict) and captured is not None
    # Percent range guard (legacy seam scope: 0..100).
    bad = False
    for w in windows:
        for key in ("percent_used", "percent_remaining"):
            v = w.get(key)
            if v is not None and (not isinstance(v, (int, float)) or not 0 <= v <= 100):
                bad = True
    now_dt = now
    stale = age_seconds(now_dt, captured) >= 300
    if bad or (error_code is not None) or (captured > now_dt):
        out = {
            "source": "fixture",
            "windows": copy.deepcopy(windows),
            "observed_at": captured_raw,
            "stale": False,
            "error_code": error_code or ("PERCENT_OUT_OF_RANGE" if bad else "FUTURE_CAPTURED_AT"),
        }
        return out
    return {"source": "fixture", "windows": copy.deepcopy(windows),
            "observed_at": captured_raw, "stale": stale, "error_code": None}


def global_snapshot(source: str, body: dict, now: datetime, error_code, last_good) -> dict:
    captured_raw = body.get("captured_at") if isinstance(body, dict) else None
    captured = parse_ts(captured_raw)
    if last_good is not None and (not isinstance(body, dict) or captured is None):
        out = copy.deepcopy(last_good)
        out["stale"] = False
        out["error_code"] = error_code or "CAPTURED_AT_INVALID"
        return out
    assert isinstance(body, dict) and captured is not None
    latest = body.get("last_reset_at", body.get("latest_reset_at"))
    f24 = body.get("forecast_24h_percent")
    f48 = body.get("forecast_48h_percent")
    bad_forecast = any(v is not None and (not isinstance(v, (int, float)) or not 0 <= v <= 100)
                       for v in (f24, f48))
    stale = age_seconds(now, captured) >= 300
    if bad_forecast or error_code is not None or captured > now:
        return {"provider": source, "fetched_at": captured_raw,
                "latest_reset_at": latest,
                "forecast_24h_percent": f24, "forecast_48h_percent": f48,
                "forecast_is_schedule": False, "stale": False,
                "error_code": error_code or ("FORECAST_OUT_OF_RANGE" if bad_forecast
                                             else "FUTURE_CAPTURED_AT")}
    return {"provider": source, "fetched_at": captured_raw,
            "latest_reset_at": latest,
            "forecast_24h_percent": f24, "forecast_48h_percent": f48,
            "forecast_is_schedule": False, "stale": stale, "error_code": None}


def error_code_for(name: str | None) -> str | None:
    if name is None:
        return None
    return {"dns": "DNS_ERROR", "tls": "TLS_ERROR",
            "http_500": "HTTP_500"}.get(name, "TRANSPORT_ERROR")


def adapt(payload: dict) -> list[dict]:
    source = payload["source"]
    events = payload["events"]
    out: list[dict] = []
    last_good = None
    for ev in events:
        now = parse_ts(ev["now"])
        assert now is not None, "event now must be RFC3339"
        body = ev.get("body")
        if isinstance(body, str):
            try:
                body = json.loads(body)
            except json.JSONDecodeError:
                body = {"__malformed__": True}
        err = error_code_for(ev.get("error"))
        if source == "fixture":
            if isinstance(body, dict) and "__malformed__" in body:
                snap = copy.deepcopy(last_good) if last_good else {
                    "source": "fixture", "windows": [], "observed_at": None,
                    "stale": False}
                snap["stale"] = False
                snap["error_code"] = "MALFORMED_BODY"
            elif not isinstance(body, dict) or body.get("captured_at") is None and err is None and last_good is None:
                # Missing captured_at on first sight: error snapshot.
                snap = {"source": "fixture", "windows": [],
                        "observed_at": None, "stale": False,
                        "error_code": "CAPTURED_AT_INVALID"}
            else:
                snap = fixture_snapshot(body, now, err, last_good)
            if snap.get("error_code") is None and isinstance(body, dict) and parse_ts(body.get("captured_at")) is not None:
                last_good = copy.deepcopy(snap)
                last_good["error_code"] = None
            elif last_good is None and snap.get("error_code") is None:
                last_good = copy.deepcopy(snap)
            out.append(snap)
        else:
            if isinstance(body, dict) and "__malformed__" in body:
                snap = copy.deepcopy(last_good) if last_good else {
                    "provider": source, "fetched_at": None,
                    "latest_reset_at": None, "forecast_24h_percent": None,
                    "forecast_48h_percent": None, "forecast_is_schedule": False,
                    "stale": False}
                snap["stale"] = False
                snap["error_code"] = "MALFORMED_BODY"
            elif body is None and err is not None and last_good is not None:
                snap = copy.deepcopy(last_good)
                snap["stale"] = False
                snap["error_code"] = err
            else:
                snap = global_snapshot(source, body, now, err, last_good)
            if snap.get("error_code") is None and isinstance(body, dict) and parse_ts(body.get("captured_at")) is not None:
                last_good = copy.deepcopy(snap)
            elif last_good is None and snap.get("error_code") is None:
                last_good = copy.deepcopy(snap)
            out.append(snap)
    return out


def main() -> int:
    raw = sys.stdin.read()
    payload = json.loads(raw)
    snapshots = adapt(payload)
    sys.stdout.write(json.dumps(snapshots, ensure_ascii=False) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

